widget.solution:
def bond_price(face, coupon, years, yld):
    p = sum(face * coupon / (1 + yld) ** t
            for t in range(1, years + 1))
    return p + face / (1 + yld) ** years

def ytm(price, face, coupon, years):
    lo, hi = 0.0, 1.0
    for _ in range(100):
        mid = (lo + hi) / 2
        if bond_price(face, coupon, years, mid) > price:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2
